// Config: edit these values for your company; nothing else in the scenario hard-codes them.
// Schedule: set this scenario to run every day at 02:00; Make keeps the schedule outside the blueprint.
return {
  "stop_flag_url": "https://<your stop list API>/stop_flags/R15.3",
  "table_api_url": "https://<your table API for the key log, decision log and exception queue>",
  "workflow_owner": "<your workflow owner>",
  "crm_url": "https://<your CRM API>",
  "lists": [
    {
      "name": "<list name>",
      "url": "https://<its API>",
      "channel": "<the channel it sends>"
    }
  ],
  "marketing_channels": [
    "email",
    "<your other marketing channels>"
  ],
  "send_status_url": "https://<your send-status record API>",
  "messaging_url": "https://<your messaging API>",
  "consent_owner": "<your systems owner>"
