// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Step 8: Read the master": "in0_Step8Readthemaster", "Step 8: Lists to check": "in1_Step8Liststocheck", "Step 8: Read the list": "in2_Step8Readthelist"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 8: Read the list";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
Object.defineProperty(Object.prototype, 'itemMatching', { value: function (i) { return this.all()[i] || this.all()[0]; }, configurable: true });
const BODIES = (out) => ({"self": JSON.stringify(out), "record_q": encodeURIComponent(out.record_id), "correct_body": JSON.stringify({ marketing_opt_out: out.opt_out }), "log_body": JSON.stringify({ recipe: 'R15.3', item: out.list + ':' + out.record_id, decision: 'nightly: ' + out.list + ' corrected to the master', rules: { list: out.list, contact: out.contact_id, opt_out: out.opt_out } })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Matched on email or phone, never name.
const normEmail = e => String(e || '').trim().toLowerCase();
const normPhone = p => String(p || '').replace(/\D/g, '');
const same = (r, ev) => (normEmail(ev.email) && normEmail(r.email) === normEmail(ev.email))
  || (normPhone(ev.phone) && normPhone(r.phone) === normPhone(ev.phone));

// Step 8: a list record that differs from the master's recorded consent for the list's channel.
const master = $('Step 8: Read the master').first().json.items || [];
const out = [];
$input.all().forEach((it, i) => {
  const l = $('Step 8: Lists to check').itemMatching(i).json;
  for (const rec of it.json.items || []) {
    const m = master.find(c => same(rec, c));
    const c = m && m.consent && m.consent[l.channel];
    if (!c || !['opted out', 'opted in'].includes(c.status)) continue;  // no recorded consent: left as is
    const want = c.status === 'opted out';
    if (rec.marketing_opt_out !== want) {
      out.push({ json: Object.assign({}, l, { record_id: rec.id, contact_id: m.id, opt_out: want }), pairedItem: i });
    }
  }
});
return out;
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };

